  <script>
    const monthNames = [
      "يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو",
      "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"
    ];

    const today = new Date();
    let viewYear = today.getFullYear();
    let viewMonth = today.getMonth();
    let selectedDate = null;
    let selectedTime = null;

    const daysElement = document.getElementById("days");
    const monthLabel = document.getElementById("monthLabel");
    const selectedDateLabel = document.getElementById("selectedDateLabel");
    const confirmButton = document.getElementById("confirmBtn");
    const toast = document.getElementById("toast");

    function sameDay(a, b) {
      return a.getFullYear() === b.getFullYear() &&
             a.getMonth() === b.getMonth() &&
             a.getDate() === b.getDate();
    }

    function renderCalendar() {
      monthLabel.textContent = `${monthNames[viewMonth]} ${viewYear}`;
      daysElement.innerHTML = "";

      const firstDay = new Date(viewYear, viewMonth, 1);
      const daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();
      const offset = (firstDay.getDay() + 1) % 7;

      for (let i = 0; i < offset; i++) {
        const empty = document.createElement("div");
        daysElement.appendChild(empty);
      }

      for (let day = 1; day <= daysInMonth; day++) {
        const date = new Date(viewYear, viewMonth, day);
        const button = document.createElement("button");
        button.className = "day";
        button.textContent = day;
        button.setAttribute("aria-label", `${day} ${monthNames[viewMonth]}`);

        if (sameDay(date, today)) button.classList.add("today");
        if (selectedDate && sameDay(date, selectedDate)) button.classList.add("selected");

        const past = date < new Date(today.getFullYear(), today.getMonth(), today.getDate());
        button.disabled = past;

        button.addEventListener("click", () => {
          selectedDate = date;
          selectedDateLabel.textContent = `${day} ${monthNames[viewMonth]}`;
          renderCalendar();
          updateButton();
        });

        daysElement.appendChild(button);
      }
    }

    document.getElementById("prevMonth").addEventListener("click", () => {
      viewMonth--;
      if (viewMonth < 0) {
        viewMonth = 11;
        viewYear--;
      }
      renderCalendar();
    });

    document.getElementById("nextMonth").addEventListener("click", () => {
      viewMonth++;
      if (viewMonth > 11) {
        viewMonth = 0;
        viewYear++;
      }
      renderCalendar();
    });

    document.querySelectorAll(".time").forEach(button => {
      button.addEventListener("click", () => {
        document.querySelectorAll(".time").forEach(item => item.classList.remove("selected"));
        button.classList.add("selected");
        selectedTime = button.dataset.time;
        updateButton();
      });
    });

    function updateButton() {
      confirmButton.disabled = !(selectedDate && selectedTime);
    }

    confirmButton.addEventListener("click", () => {
      if (!selectedDate || !selectedTime) return;
      const formattedDate = selectedDate.toLocaleDateString("ar-QA", {
        day: "numeric",
        month: "long",
        year: "numeric"
      });
      toast.textContent = `تم تأكيد موعدك يوم ${formattedDate} الساعة ${selectedTime}`;
      toast.classList.add("show");
      setTimeout(() => toast.classList.remove("show"), 3200);
    });

    renderCalendar();
  </script>
